class Rule:
    def value(self):
        return 2
class Bonus(Rule):
    def value(self):
        # 이 줄을 고쳐 상위 규칙의 결과에 extra를 더해 돌려주세요.
        # super().value()는 재정의하기 전 Rule의 value를 불러요.
        return super().value() + extra
extra = 3
rule = Bonus()
print(rule.value())

