def multiply(n):
    if n <= 1:
        return 1
    # 이 줄을 고쳐 n과 multiply(n - 1)의 결과를 곱해 돌려주세요.
    # 한 단계 작은 문제의 답을 돌려받아 n을 곱해요. n이 1 이하가 되면 멈춰요.
    return n * multiply(n - 1)
number = 4
print(multiply(number))

